// Writes the two reference pages that come from the code:
//
//   src/content/docs/reference/tokens.md      from aurora-leptos/style/tokens.css,
//                                             style/hyper.css and src/tokens.rs
//   src/content/docs/reference/components.md  from the #[component] functions
//                                             in aurora-leptos/src/
//
//   node scripts/gen-reference.mjs           write the pages
//   node scripts/gen-reference.mjs --check   exit 1 if a page is not current
//
// Run it from docs/. Do not edit the two pages by hand: change the code, or
// the text in this script, and run it again.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const DOCS = join(dirname(fileURLToPath(import.meta.url)), '..');
const CRATE = join(DOCS, '..', 'aurora-leptos');
const OUT = join(DOCS, 'src', 'content', 'docs', 'reference');
const read = (p) => readFileSync(join(CRATE, p), 'utf8');

const NOTE = '<!-- Generated by docs/scripts/gen-reference.mjs. Do not edit. -->';

// ---------------------------------------------------------------------------
// Tokens
// ---------------------------------------------------------------------------

// What each colour token is for. The values come from the CSS.
const PURPOSE = {
	bg: 'The page.',
	sidebar: 'The side navigation.',
	panel: 'A panel or card.',
	'panel-2': 'A second surface, one step from `--panel`: a modal footer, a row or card under the pointer.',
	inset: 'A sunken surface: inline code, code blocks, logs, the track of a segmented control.',
	field: 'The inside of an input, a select or a text area.',
	control: 'The fill of a control: a default button, a segment, the track of a switch.',
	'control-hover': 'A control or a row under the pointer.',
	border: 'A border.',
	'border-soft': 'A soft border: table rows, the header of a panel or a modal.',
	'border-fainter': 'The faintest line (the grid of a Hlin chart).',
	'border-control': 'The edge of an input, a select or a switch. 3:1 on the surfaces.',
	fg: 'Body text.',
	'fg-bright': 'The strongest text: titles.',
	'fg-2': 'Second text: labels, table cells.',
	'fg-strong': 'Strong text, between `--fg` and `--fg-bright`.',
	muted: 'Quiet text. Also the "idle" or "pending" status hue.',
	faint: 'Faint text: placeholders, captions, panel titles.',
	fainter: 'Large text, disabled text and decoration only (3:1, not 4.5:1).',
	ice: 'Hue: the accent. Links, filled buttons, "running".',
	teal: 'Hue: teal.',
	violet: 'Hue: violet. "Scheduled".',
	gold: 'Hue: warning. "Cancelled".',
	ok: 'Hue: success. "Completed".',
	bad: 'Hue: danger. "Failed".',
	skip: 'Hue: "skipped".',
	'on-status': 'Text on a solid status fill (a count badge).',
	'on-accent': 'Text on a solid accent fill: a filled button, an active chip.',
	'bad-muted': 'Second error text: the detail line under an error.',
	edge: 'The edges of the graph. 3:1 on the panels.',
	'brand-stroke': 'The stroke of a brand mark (a product logo).',
	'ice-3': 'The ice scale, step 3: for hover and active on ice fills.',
	'ice-5': 'The ice scale, step 5: a filled button under the pointer.',
	'ice-7': 'The ice scale, step 7: a filled button while it is pressed.',
	'tooltip-bg': 'The fill of a tooltip.',
	'tooltip-fg': 'The text of a tooltip.',
	'tooltip-border': 'The border of a tooltip.',
	scrim: 'The shade behind a drawer or the open side navigation.',
	'shadow-sm': 'A small shadow: a tooltip, a card under the pointer.',
	'shadow-md': 'A medium shadow: a menu, a toast, the sign-in card.',
	'shadow-lg': 'A large shadow: a modal, a drawer.',
	scrollbar: 'The thumb of a scrollbar.',
	'aurora-2': 'The Aurora gradient: teal to ice.',
	'aurora-3': 'The Aurora gradient: teal, ice, violet.',
};
const HUES = ['ice', 'teal', 'violet', 'gold', 'ok', 'bad', 'skip', 'muted'];
for (const h of HUES) {
	PURPOSE[`${h}-fg`] = `Text on the \`--${h}-bg\` fill (a pill, a badge).`;
	PURPOSE[`${h}-bg`] = `The tinted fill behind \`--${h}-fg\`.`;
}

/** `--name: value;` declarations of the first block that matches `selector`. */
function declarations(css, selector) {
	const out = [];
	let at = 0;
	for (;;) {
		const start = css.indexOf(selector, at);
		if (start < 0) break;
		const open = css.indexOf('{', start);
		const close = css.indexOf('}', open);
		const body = css.slice(open + 1, close).replace(/\/\*[\s\S]*?\*\//g, '');
		for (const m of body.matchAll(/--([a-z0-9-]+)\s*:\s*([^;]+);/g)) {
			out.push({ name: m[1], value: m[2].replace(/\s+/g, ' ').trim() });
		}
		at = close;
	}
	return out;
}

/** The arguments of a call at the top level: `a, f(b, c)` -> [a, f(b, c)]. */
function splitArgs(s) {
	const out = [];
	let depth = 0;
	let cur = '';
	for (const ch of s) {
		if (ch === '(') depth++;
		if (ch === ')') depth--;
		if (ch === ',' && depth === 0) {
			out.push(cur.trim());
			cur = '';
		} else cur += ch;
	}
	out.push(cur.trim());
	return out;
}

/** `value` with each `light-dark(a, b)` replaced by `a` (light) or `b` (dark). */
function resolve(value, dark) {
	let out = value;
	for (;;) {
		const i = out.indexOf('light-dark(');
		if (i < 0) return out;
		let depth = 0;
		let j = i + 'light-dark'.length;
		for (; j < out.length; j++) {
			if (out[j] === '(') depth++;
			if (out[j] === ')' && --depth === 0) break;
		}
		const [light, darkValue] = splitArgs(out.slice(i + 'light-dark('.length, j));
		out = out.slice(0, i) + (dark ? darkValue : light) + out.slice(j + 1);
	}
}

const code = (s) => '`' + s.replace(/\|/g, '\\|') + '`';

function tokensPage() {
	const tokensCss = read('style/tokens.css');
	const hyperCss = read('style/hyper.css');
	const rust = new Map(
		[...read('src/tokens.rs').matchAll(/pub const ([A-Z_]+): &str = "var\(--([a-z0-9-]+)\)";/g)].map((m) => [m[2], m[1]]),
	);
	// The second `:root {` block holds the tokens; the first sets color-scheme.
	const all = declarations(tokensCss, ':root {');
	const hyper = new Map(declarations(hyperCss, ':root[data-theme="hyper"]').map((d) => [d.name, d.value]));

	const colours = all.filter((d) => d.name in PURPOSE);
	const other = all.filter((d) => !(d.name in PURPOSE));

	const swatch = (name) =>
		name.startsWith('shadow')
			? `<span style="display:inline-block;width:1.6em;height:1.2em;border-radius:var(--radius-sm);background:var(--panel);box-shadow:var(--${name})"></span>`
			: `<span style="display:inline-block;width:1.6em;height:1.2em;border-radius:var(--radius-sm);border:1px solid var(--border);background:var(--${name})"></span>`;

	const rows = colours.map(({ name, value }) => {
		const light = resolve(value, false);
		const dark = resolve(value, true);
		const h = hyper.has(name) ? code(hyper.get(name)) : light === dark ? 'the same' : 'the dark value';
		const tok = rust.has(name) ? `${code('--' + name)}<br/>${code('token::' + rust.get(name))}` : code('--' + name);
		const values = `Light: ${code(light)}<br/>Dark: ${light === dark ? 'the same' : code(dark)}<br/>Hyper: ${h}`;
		return `| ${swatch(name)} | ${tok} | ${values} | ${PURPOSE[name]} |`;
	});

	const group = (prefix) => other.filter((d) => d.name.startsWith(prefix)).map((d) => `| ${code('--' + d.name)} | ${code(d.value)} |`);
	const rest = other.filter((d) => !['radius-', 'space-', 'fs-', 'h-', 'font-'].some((p) => d.name.startsWith(p)));
	if (rest.length) throw new Error(`tokens with no purpose: ${rest.map((d) => d.name).join(', ')}`);

	return `---
title: Tokens
description: Each Aurora token, its light, dark and hyper value, and what it is for.
sidebar:
  order: 2
---

${NOTE}

Aurora's tokens are CSS custom properties. They are defined in
[\`style/tokens.css\`](https://github.com/colliery-io/aurora/blob/main/aurora-leptos/style/tokens.css),
and hyper sets its own values in
[\`style/hyper.css\`](https://github.com/colliery-io/aurora/blob/main/aurora-leptos/style/hyper.css).
This page is made from those two files.

The swatch shows the token in the theme that this site shows now. Change the
theme with the select in the header to see the other values.

## Colours

A colour token holds a light and a dark value: \`--x: light-dark(<light>, <dark>)\`.
"The same" means that one value serves each theme. In hyper, "the dark value"
means that hyper does not set the token: hyper has a dark base, so the token
takes its dark value. A \`-bg\` token is a tint of its hue, so it follows the
hue in each theme.

In Rust, \`token::X\` is the string \`"var(--x)"\`. The tokens with no Rust
constant are used by the stylesheet; in Rust, write \`"var(--name)"\`.

| | Token | Values | Use |
|---|---|---|---|
${rows.join('\n')}

## Radii

| Token | Value |
|---|---|
${group('radius-').join('\n')}

## Spacing

| Token | Value |
|---|---|
${group('space-').join('\n')}

## Font sizes

| Token | Value |
|---|---|
${group('fs-').join('\n')}

## Control heights

| Token | Value |
|---|---|
${group('h-').join('\n')}

## Font families

| Token | Value |
|---|---|
${group('font-').join('\n')}

## Colour helpers in Rust

These functions are in \`aurora_leptos::tokens\`.

| Function | Gives |
|---|---|
| \`tint(color, pct)\` | \`color\` at \`pct\` per cent opacity: \`color-mix(in srgb, <color> <pct>%, transparent)\`. |
| \`fill_for(color)\` | The fill for \`color\`: \`var(--x-bg)\` for a hue token, else an 11% tint. |
| \`fg_for(color)\` | The text colour on that fill: \`var(--x-fg)\` for a hue token, else \`color\`. |
| \`pill_bg(color)\` | The same as \`fill_for\`. |
| \`status_color(status)\` | The hue token of a status text (see [Components](../components/#statusbadge)). |
`;
}

// ---------------------------------------------------------------------------
// Components
// ---------------------------------------------------------------------------

// The modules, in the order of the page. `use` is the path that imports them.
const MODULES = [
	{ file: 'src/lib.rs', title: 'Stylesheet', use: 'aurora_leptos::AuroraStyles' },
	{ file: 'src/theme.rs', title: 'Theme', use: 'aurora_leptos::theme::ThemeToggle' },
	{ file: 'src/components.rs', title: 'Primitives', use: 'aurora_leptos::components::*' },
	{ file: 'src/frame.rs', title: 'Frame', use: 'aurora_leptos::components::*' },
	{ file: 'src/data.rs', title: 'Data', use: 'aurora_leptos::components::*' },
	{ file: 'src/widgets.rs', title: 'Widgets', use: 'aurora_leptos::widgets::*' },
	{ file: 'src/graph.rs', title: 'Graph', use: 'aurora_leptos::graph::*' },
];

// A purpose for the components that have no doc comment (from INVENTORY.md).
const FALLBACK = {
	AuroraStyles:
		'Puts the full Aurora stylesheet in an inline `<style>`. `hyper=true` adds the opt-in hyper theme. A linked stylesheet has no first-paint flash: see [Load the stylesheet as a file](../../how-to/link-the-stylesheet/).',
	Stack: 'A vertical flex column. `gap`: `"xs"` or `"sm"` (default `md`). `center` centres the children.',
	Text: 'A paragraph of text. `size`: `"xs"`, `"sm"` or `"lg"`. `dimmed`, `bright`, `bold` and `mono` change its look.',
	Pill: 'A small tinted label. Give it a hue token (`token::OK`): the text is `--x-fg` on the `--x-bg` fill. Any other colour gets an 11% tint.',
	StatusBadge:
		'A status as a pill. The hue comes from `status_color(status)`: running is ice, completed ok, failed bad, scheduled violet, pending and paused muted, cancelled gold, skipped skip. Any other text is muted. The case does not matter.',
	Dot: 'A small round status dot in `color`. `size` is in px. `glow` adds a soft ring.',
	Panel: 'A card surface with a title and an optional caption.',
	Loading: 'The "loading" state of a view: a spinner and a label.',
	ErrorState: 'The "error" state of a view. It classifies the `ApiError` (not authorised, not found, invalid, server, network) and shows a retry button when `on_retry` is given and the error can be retried.',
	BuildStatusBadge: 'A CI build state as a pill: success is ok, failed bad, building ice, pending and other text muted.',
};

/** The doc comment lines that end at line `i` (exclusive), as markdown. */
function docAbove(lines, i) {
	const doc = [];
	for (let j = i - 1; j >= 0; j--) {
		const t = lines[j].trim();
		if (t.startsWith('///')) doc.unshift(t.replace(/^\/\/\/ ?/, ''));
		else if (t.startsWith('#[')) continue;
		else break;
	}
	return doc;
}

/** Rustdoc markdown to page markdown: no intra-doc links, no headings. */
function cleanDoc(doc) {
	let inCode = false;
	return doc
		.map((l) => {
			if (l.startsWith('```')) {
				inCode = !inCode;
				return inCode && (l === '```' || l === '```ignore' || l === '```no_run') ? '```rust' : l;
			}
			if (inCode) return l;
			return l
				.replace(/^#+ (.*)$/, '**$1**')
				.replace(/\[([^\]]+)\]\((?:crate|super|self)::[^)]*\)/g, '$1')
				.replace(/\[(`[^`\]]+`)\](?!\()/g, '$1');
		})
		.join('\n')
		.trim();
}

/** Split at top-level commas (parentheses, brackets and angle brackets). */
function splitParams(s) {
	const out = [];
	let depth = 0;
	let cur = '';
	for (let i = 0; i < s.length; i++) {
		const ch = s[i];
		if ('([<{'.includes(ch)) depth++;
		if (')]}'.includes(ch) || (ch === '>' && s[i - 1] !== '-')) depth--;
		if (ch === ',' && depth === 0) {
			out.push(cur);
			cur = '';
		} else cur += ch;
	}
	if (cur.trim()) out.push(cur);
	return out;
}

function parseProp(raw) {
	const docs = [];
	const text = raw
		.split('\n')
		.filter((l) => {
			const t = l.trim();
			if (t.startsWith('///')) {
				docs.push(t.replace(/^\/\/\/ ?/, '').replace(/\u0001/g, ','));
				return false;
			}
			return true;
		})
		.join(' ')
		.replace(/\s+/g, ' ')
		.trim();
	const attr = text.match(/^#\[prop\(([\s\S]*?)\)\]\s*/);
	let rest = attr ? text.slice(attr[0].length) : text;
	const flags = attr ? splitArgs(attr[1].trim()) : [];
	const [name, ...type] = rest.split(':');
	const def = flags.find((f) => f.startsWith('default'));
	let when;
	if (def) when = '`' + def.replace(/^default\s*=\s*/, '').replace(/\.to_string\(\)/, '').replace(/\|/g, '\\|') + '`';
	else if (flags.includes('optional') || /^Option</.test(type.join(':').trim())) when = 'optional';
	else when = 'required';
	return { name: name.trim(), type: type.join(':').trim(), when, doc: docs.join(' ') };
}

function components(file) {
	const src = read(file).replace(/^\s*\/\/\/.*$/gm, (l) => l.replace(/,/g, '\u0001'));
	const lines = src.split('\n');
	const out = [];
	for (let i = 0; i < lines.length; i++) {
		if (lines[i].trim() !== '#[component]') continue;
		const head = lines.slice(i + 1).join('\n');
		const m = head.match(/^\s*pub fn ([A-Z][A-Za-z0-9]*)\(/);
		if (!m) continue;
		// The parameter list: up to the `)` that matches the first `(`.
		const open = head.indexOf('(');
		let depth = 0;
		let close = open;
		for (; close < head.length; close++) {
			if (head[close] === '(') depth++;
			if (head[close] === ')' && --depth === 0) break;
		}
		const props = splitParams(head.slice(open + 1, close)).map(parseProp).filter((p) => p.name);
		const doc = docAbove(lines, i).map((l) => l.replace(/\u0001/g, ','));
		out.push({ name: m[1], doc: doc.length ? cleanDoc(doc) : FALLBACK[m[1]] ?? '', props });
	}
	return out;
}

function propTable(props) {
	if (!props.length) return 'No props.';
	// A Note column only when a prop has a doc comment of its own.
	if (!props.some((p) => p.doc)) {
		const rows = props.map((p) => `| \`${p.name}\` | ${code(p.type)} | ${p.when} |`);
		return ['| Prop | Type | Default |', '|---|---|---|', ...rows].join('\n');
	}
	const rows = props.map((p) => `| \`${p.name}\` | ${code(p.type)} | ${p.when} | ${cleanDoc([p.doc]).replace(/\|/g, '\\|')} |`);
	return ['| Prop | Type | Default | Note |', '|---|---|---|---|', ...rows].join('\n');
}

function iconsSection() {
	const src = read('src/icons.rs');
	const body = src.slice(src.indexOf('icons! {'));
	const lines = body.split('\n');
	const rows = [];
	for (let i = 0; i < lines.length; i++) {
		const m = lines[i].match(/^\s*(Icon[A-Za-z]+),\s*(true|false),/);
		if (!m) continue;
		const doc = docAbove(lines, i).join(' ');
		rows.push(`| \`${m[1]}\` | ${m[2] === 'true' ? 'filled' : 'outline'} | ${doc} |`);
	}
	return `## Icons

\`use aurora_leptos::components::*;\` (or \`aurora_leptos::icons::*\`)

Small SVG icons in \`currentColor\`: an icon takes the text colour of its
parent. Each icon has two props:

| Prop | Type | Default | Note |
|---|---|---|---|
| \`size\` | \`u32\` | \`16\` | The width and the height, in px. |
| \`title\` | \`String\` | optional | The accessible name. With a title the icon is \`role="img"\`; without one it is \`aria-hidden\`. |

\`IconChevron\` also has \`dir\` (\`String\`, optional): the way it points.

| Icon | Drawn | Note |
|---|---|---|
${rows.join('\n')}`;
}

function componentsPage() {
	const sections = MODULES.map(({ file, title, use }) => {
		const list = components(file);
		if (!list.length) throw new Error(`no components in ${file}`);
		const body = list.map((c) => `### ${c.name}\n\n${c.doc}\n\n${propTable(c.props)}`).join('\n\n');
		return `## ${title}\n\n\`use ${use};\`\n\n${body}`;
	});
	return `---
title: Components
description: Each Aurora component, its props, and what it is for.
sidebar:
  order: 3
---

${NOTE}

This page is made from the \`#[component]\` functions in
[\`aurora-leptos/src/\`](https://github.com/colliery-io/aurora/tree/main/aurora-leptos/src)
and their doc comments. For the types that the props take (\`ApiError\`,
\`DagNode\`, \`LogLine\`, ...), see the
[API reference on docs.rs](https://docs.rs/colliery-io-aurora). To see each
component on a page, [run the gallery](../../how-to/run-the-gallery/).

"Default" is the value of a prop that you do not give. "Optional" means the
prop is empty when you do not give it (an empty string, \`false\`, \`None\`).
A prop marked "required" must be given.

A prop of type \`Signal<T>\` takes a value, a signal or a closure. A prop of
type \`Option<Callback<T>>\` takes a \`Callback::new(...)\`.

${sections.join('\n\n')}

${iconsSection()}
`;
}

// ---------------------------------------------------------------------------

const pages = { 'tokens.md': tokensPage(), 'components.md': componentsPage() };
const check = process.argv.includes('--check');
let stale = 0;
for (const [name, text] of Object.entries(pages)) {
	const path = join(OUT, name);
	if (check) {
		if (!existsSync(path) || readFileSync(path, 'utf8') !== text) {
			console.error(`${name} is not current: run node scripts/gen-reference.mjs in docs/`);
			stale++;
		}
	} else {
		writeFileSync(path, text);
		console.log(`wrote ${path}`);
	}
}
if (check) {
	if (stale) process.exit(1);
	console.log('the reference pages are current');
}
